insert into detective_cases(id, slug, title, title_ar, description, description_ar, case_type, difficulty, age_min, age_max, status, created_by, category, estimated_minutes, briefing, briefing_ar, objective, objective_ar, cover_image_path) values ('4c67a84b-65c8-5221-a079-bbb3922211e3', $q$the-blue-moonflower-seed$q$, $q$The Vanishing Blue Moonflower Seed$q$, $q$سر اختفاء بذرة زهرة القمر الزرقاء$q$, $q$A rare blue moonflower seed packet has vanished from a greenhouse display just before the school garden showcase. The display case is intact, and the location card still names the display shelf. Inspect the humidity log, transfer note, and storage records before deciding what happened.$q$, $q$اختفت حافظة بذور نادرة لزهرة القمر الزرقاء من معرض البيت الزجاجي قبيل عرض حديقة المدرسة. صندوق العرض سليم، وبطاقة الموقع ما زالت تشير إلى رف العرض. افحص سجل الرطوبة ومذكرة النقل وسجلات التخزين قبل أن تقرر ما حدث.$q$, 'FULL', 2, 10, 16, 'DRAFT', v_user, $q$الملاحظة والسجلات$q$, 20, $q$At 3:30 p.m., student volunteer Farah found the moonflower display empty. A small blue-flower symbol on the stand identifies the missing packet as collection item S-12. The glass cover and latch are intact. Greenhouse supervisor Salma says humidity rose above the safe limit; inventory helper Omar says the location card still lists the display shelf. Follow the records. An empty stand shows that an object is absent from that spot, but it does not by itself tell you who moved it or why.$q$, $q$في الساعة ٣:٣٠ عصرًا، وجدت المتطوعة الطالبة فرح منصة زهرة القمر فارغة. يحدد رمز الزهرة الزرقاء على المنصة الحافظة المفقودة بوصفها العينة S-12 من المجموعة. الغطاء الزجاجي والمزلاج سليمان. تقول مشرفة البيت الزجاجي سلمى إن الرطوبة تجاوزت الحد الآمن، بينما يقول مساعد الجرد عمر إن بطاقة الموقع ما زالت تشير إلى رف العرض. تتبّع السجلات. يثبت خلو المنصة أن الغرض غير موجود في ذلك الموضع، لكنه لا يحدد وحده من نقله أو لماذا.$q$, $q$Separate direct observations from explanations, use independent records to trace an item, and avoid treating absence or access as proof of theft.$q$, $q$ميّز بين الملاحظات المباشرة والتفسيرات، واستخدم سجلات مستقلة لتتبّع غرض، ولا تعتبر غيابه أو إمكانية الوصول إليه دليلًا على السرقة.$q$, 'demo/detective/blue-moonflower-seed/cover.webp') on conflict (id) do nothing;
insert into detective_case_versions(id, case_id, version_number, status, created_by) values ('f1f57913-2d9f-5ada-9cb8-1326514fc97a', '4c67a84b-65c8-5221-a079-bbb3922211e3', 1, 'DRAFT', v_user) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('75a2cb26-9bc2-56ae-9aa8-e4f4bc268f5d', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$inspect$q$, 1, $q$Inspect the Empty Display$q$, $q$افحص منصة العرض الفارغة$q$, $q${}$q$::jsonb) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('176c6d9c-4a18-59f4-9e63-25520bf55431', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$trace$q$, 2, $q$Trace the Paper Trail$q$, $q$تتبّع أثر السجلات$q$, $q${"requires_stage":"inspect"}$q$::jsonb) on conflict (id) do nothing;
insert into detective_stages(id, version_id, stage_key, position, title, title_ar, unlock_rule) values ('62bb4bab-567a-599d-bc16-8ab522921893', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$resolve$q$, 3, $q$Resolve the Mystery$q$, $q$حلّ اللغز$q$, $q${"requires_stage":"trace"}$q$::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('fd9ef087-bb27-52c6-b540-65ddcc00d581', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', 1, $q$The Greenhouse Display$q$, $q$معرض البيت الزجاجي$q$, 'demo/detective/blue-moonflower-seed/scene-1.webp', $q$The school showcase is about to begin. The glass display is still standing, but the blue moonflower packet is no longer on its labeled cradle. Inspect the case, the damp shelf, and the flower symbol before guessing why it is empty.$q$, $q$يوشك عرض المدرسة على البدء. ما زال صندوق العرض الزجاجي في مكانه، لكن حافظة بذور زهرة القمر الزرقاء لم تعد على قاعدتها المحددة. افحص الصندوق والرف الرطب ورمز الزهرة قبل تخمين سبب فراغه.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('6c281158-0402-5afb-bc49-24188314740f', 'fd9ef087-bb27-52c6-b540-65ddcc00d581', $q$empty_display$q$, $q$The empty, closed display$q$, $q$The empty, closed display$q$, $q$صندوق العرض المغلق والفارغ$q$, 8, 18, 24, 35, $q$The small display cradle is empty. Its glass cover and latch appear intact. This establishes that the packet is not currently on the stand; it does not show who moved it or whether it was stolen.$q$, $q$قاعدة العرض الصغيرة فارغة، ويبدو غطاؤها الزجاجي ومزلاجها سليمين. يثبت ذلك أن الحافظة ليست على المنصة الآن، لكنه لا يبين من نقلها أو إن كانت قد سُرقت.$q$, $q$ملاحظة مباشرة عن المكان والحالة الظاهرة فقط؛ لا تستنتج منها هوية شخص أو سبب الغياب.$q$, $q$ملاحظة مباشرة عن المكان والحالة الظاهرة فقط؛ لا تستنتج منها هوية شخص أو سبب الغياب.$q$, $q$FACT$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('c9c9f22a-3faf-532d-9ba2-749ddf46953d', 'fd9ef087-bb27-52c6-b540-65ddcc00d581', $q$humidity_clue$q$, $q$Condensation near the humidity gauge$q$, $q$Condensation near the humidity gauge$q$, $q$تكاثف قرب مقياس الرطوبة$q$, 42, 21, 15, 44, $q$Water beads gather on the shelf beside the greenhouse humidity gauge. The image suggests damp conditions, but the exact reading and the safe storage limit must be checked in the written log and care guide.$q$, $q$تتجمع قطرات ماء على الرف قرب مقياس رطوبة البيت الزجاجي. يوحي المشهد بظروف رطبة، لكن يجب مراجعة القراءة الدقيقة وحد التخزين الآمن في السجل ودليل العناية.$q$, $q$قرينة بصرية على الرطوبة، وليست وحدها إثباتًا أن الرطوبة تجاوزت الحد أو أن النقل كان ضروريًا.$q$, $q$قرينة بصرية على الرطوبة، وليست وحدها إثباتًا أن الرطوبة تجاوزت الحد أو أن النقل كان ضروريًا.$q$, $q$OBSERVATION$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('78b099f1-b7c0-5248-951d-cfcca617c397', 'fd9ef087-bb27-52c6-b540-65ddcc00d581', $q$flower_identity_tag$q$, $q$The blue moonflower symbol$q$, $q$The blue moonflower symbol$q$, $q$رمز زهرة القمر الزرقاء$q$, 78, 69, 9, 14, $q$A blue moonflower symbol remains on the empty display cradle. The same collection symbol appears on the packet sleeve in the storage scene, helping identify the item without proving how it got there.$q$, $q$يبقى رمز زهرة القمر الزرقاء على قاعدة العرض الفارغة. ويظهر الرمز نفسه على حافظة البذور في مشهد التخزين، ما يساعد على تحديد العينة دون أن يثبت كيف وصلت إلى هناك.$q$, $q$رمز تعريف للمقارنة بين المشاهد، لا دليل اتهام ولا تفسير مستقل لعملية النقل.$q$, $q$رمز تعريف للمقارنة بين المشاهد، لا دليل اتهام ولا تفسير مستقل لعملية النقل.$q$, $q$FACT$q$, 3, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('7b500ea4-361a-519e-8d86-f99bac811e70', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', 2, $q$The Greenhouse Records Bench$q$, $q$منضدة سجلات البيت الزجاجي$q$, 'demo/detective/blue-moonflower-seed/scene-2.webp', $q$The workbench holds a humidity log, a signed transfer slip, and a location card that still points to the display. Compare the time and status on each record; a card can be out of date without being false about what it once recorded.$q$, $q$تضم منضدة العمل سجل رطوبة ومذكرة نقل موقعة وبطاقة موقع ما زالت تشير إلى منصة العرض. قارن الوقت والحالة في كل سجل؛ فقد تصبح البطاقة قديمة دون أن تكون كاذبة بشأن ما سجلته سابقًا.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('4bb8d075-ca1e-5fd8-a649-1df751261c58', '7b500ea4-361a-519e-8d86-f99bac811e70', $q$humidity_log$q$, $q$The 3:06 humidity reading$q$, $q$The 3:06 humidity reading$q$, $q$قراءة الرطوبة عند ٣:٠٦$q$, 1, 49, 40, 46, $q$The signed greenhouse log records 86% humidity at 3:06 p.m. The seed-care guide says packets should be moved to the dry cabinet when humidity rises above 80%. The entry predates the report that the display was empty.$q$, $q$يسجل دفتر البيت الزجاجي الموقع رطوبة بنسبة ٨٦٪ عند ٣:٠٦ عصرًا. وينص دليل العناية بالبذور على نقل الحافظات إلى الخزانة الجافة إذا تجاوزت الرطوبة ٨٠٪. ويسبق التسجيل بلاغ خلو المنصة.$q$, $q$السجل يتجاوز عتبة النقل المحددة في دليل العناية؛ هذا يدعم سببًا عمليًا لكنه لا يحدد وحده من نقل الحافظة.$q$, $q$السجل يتجاوز عتبة النقل المحددة في دليل العناية؛ هذا يدعم سببًا عمليًا لكنه لا يحدد وحده من نقل الحافظة.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44', '7b500ea4-361a-519e-8d86-f99bac811e70', $q$signed_transfer_slip$q$, $q$The signed S-12 transfer slip$q$, $q$The signed S-12 transfer slip$q$, $q$مذكرة نقل العينة S-12 الموقعة$q$, 40, 44, 26, 39, $q$A transfer slip for collection item S-12 is signed by greenhouse supervisor Salma at 3:10 p.m. It directs the packet from the display cradle to dry cabinet B after the humidity reading exceeded the care limit.$q$, $q$تحمل مذكرة نقل العينة S-12 توقيع مشرفة البيت الزجاجي سلمى عند ٣:١٠ عصرًا، وتوجّه بنقل الحافظة من منصة العرض إلى الخزانة الجافة B بعد تجاوز قراءة الرطوبة حد العناية.$q$, $q$أقوى سجل يثبت أن النقل كان موثقًا ومصرحًا به قبل اكتشاف المنصة الفارغة.$q$, $q$أقوى سجل يثبت أن النقل كان موثقًا ومصرحًا به قبل اكتشاف المنصة الفارغة.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('6882f652-c0a1-5201-9825-a2631f8c1389', '7b500ea4-361a-519e-8d86-f99bac811e70', $q$stale_location_card$q$, $q$The old display-location card$q$, $q$The old display-location card$q$, $q$بطاقة الموقع القديمة$q$, 74, 35, 23, 39, $q$The inventory card still lists the display cradle as the packet's location. Its update box is blank. This conflicts with the newer transfer slip, but it may simply be a lagging location record rather than proof that the packet disappeared from the greenhouse.$q$, $q$ما زالت بطاقة الجرد تذكر منصة العرض موقعًا للحافظة، وخانة التحديث فارغة. يتعارض ذلك مع مذكرة النقل الأحدث، لكنه قد يكون تأخرًا في تحديث الموقع لا دليلًا على اختفاء الحافظة من البيت الزجاجي.$q$, $q$سجل قديم لم يُحدّث؛ يفسر الالتباس الإداري ولا يثبت السرقة أو الإهمال المتعمد.$q$, $q$سجل قديم لم يُحدّث؛ يفسر الالتباس الإداري ولا يثبت السرقة أو الإهمال المتعمد.$q$, $q$OBSERVATION$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('5295429f-832b-53ed-b232-f1dbdc1e92d4', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', 3, $q$The Dry Storage Cabinet$q$, $q$خزانة التخزين الجاف$q$, 'demo/detective/blue-moonflower-seed/scene-3.webp', $q$Cabinet B is closed in the seed-storage nook. Look for the matching packet sleeve, the cabinet record, and the intact closure. A matching item and a documented handoff can answer where it went without turning a routine move into an accusation.$q$, $q$الخزانة B مغلقة في ركن تخزين البذور. ابحث عن حافظة البذور المطابقة وسجل الخزانة والإغلاق السليم. يمكن للغرض المطابق والتسليم الموثق أن يجيبا عن مكانه دون تحويل نقل روتيني إلى اتهام.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('f263d153-3fee-5b8c-b1d6-0cc5ca59f17b', '5295429f-832b-53ed-b232-f1dbdc1e92d4', $q$seed_packet_in_cabinet$q$, $q$The S-12 packet in dry storage$q$, $q$The S-12 packet in dry storage$q$, $q$حافظة S-12 في التخزين الجاف$q$, 12, 34, 10, 18, $q$A packet bearing the same blue moonflower collection symbol is safely stored inside dry cabinet B. The inventory register identifies it as item S-12, the same packet listed on the transfer slip.$q$, $q$توجد حافظة تحمل رمز زهرة القمر الزرقاء نفسه محفوظة بأمان داخل الخزانة الجافة B. ويحددها سجل الجرد بوصفها العينة S-12 نفسها المذكورة في مذكرة النقل.$q$, $q$يثبت تطابق الرمز والسجل العثور على العينة في موقع التخزين المحدد.$q$, $q$يثبت تطابق الرمز والسجل العثور على العينة في موقع التخزين المحدد.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('6f024c76-7e18-52b4-a743-f710dd318e12', '5295429f-832b-53ed-b232-f1dbdc1e92d4', $q$cabinet_handoff_log$q$, $q$The 3:16 cabinet handoff entry$q$, $q$The 3:16 cabinet handoff entry$q$, $q$قيد تسليم الخزانة عند ٣:١٦$q$, 33, 48, 34, 22, $q$The cabinet log records item S-12 placed in cabinet B at 3:16 p.m. under Salma's initials. The entry is four minutes after the transfer slip and fourteen minutes before Farah noticed the empty display.$q$, $q$يسجل دفتر الخزانة وضع العينة S-12 في الخزانة B عند ٣:١٦ عصرًا بأحرف اسم سلمى. يأتي القيد بعد مذكرة النقل بأربع دقائق وقبل ملاحظة فرح للمنصة الفارغة بأربع عشرة دقيقة.$q$, $q$سجل مستقل في موقع التخزين يطابق مذكرة النقل زمنيًا ويحدد مكان العينة.$q$, $q$سجل مستقل في موقع التخزين يطابق مذكرة النقل زمنيًا ويحدد مكان العينة.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('3e41adf7-4737-5671-89d4-4ef68ded21ee', '5295429f-832b-53ed-b232-f1dbdc1e92d4', $q$intact_cabinet_seal$q$, $q$The intact cabinet closure$q$, $q$The intact cabinet closure$q$, $q$إغلاق الخزانة السليم$q$, 75, 28, 18, 41, $q$The dry cabinet latch and numbered tie are intact. This supports that the cabinet has remained closed since the recorded storage handoff; it does not prove every action that occurred before the packet was placed inside.$q$, $q$مزلاج الخزانة الجافة والرباط المرقم سليمان. يدعم ذلك بقاء الخزانة مغلقة منذ تسليم التخزين المسجل، لكنه لا يثبت كل ما جرى قبل وضع الحافظة بداخلها.$q$, $q$قرينة على سلامة التخزين بعد الإيداع، ولا تثبت وحدها تفاصيل المراحل السابقة.$q$, $q$قرينة على سلامة التخزين بعد الإيداع، ولا تثبت وحدها تفاصيل المراحل السابقة.$q$, $q$OBSERVATION$q$, 3, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('0471458c-7bd4-5a83-a750-313aac8b6ce7', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', 'c9c9f22a-3faf-532d-9ba2-749ddf46953d', '4bb8d075-ca1e-5fd8-a649-1df751261c58', $q$SUPPORTS$q$, $q$The visible condensation is consistent with the recorded high humidity, but the log provides the measured value.$q$, $q$يتفق التكاثف الظاهر مع الرطوبة المرتفعة المسجلة، لكن الدفتر هو مصدر القراءة المقاسة.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('58313b5d-52ca-57bf-87ef-e90134b91757', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '4bb8d075-ca1e-5fd8-a649-1df751261c58', 'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44', $q$SUPPORTS$q$, $q$The recorded 86% reading exceeds the seed-care guide's 80% limit and precedes the signed transfer.$q$, $q$تتجاوز قراءة ٨٦٪ الحد ٨٠٪ في دليل العناية، وتسبق مذكرة النقل الموقعة.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('ce394ff8-a653-5af4-80d9-1a45ac1fe853', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', 'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44', '6f024c76-7e18-52b4-a743-f710dd318e12', $q$TEMPORAL$q$, $q$The cabinet entry follows the signed transfer by six minutes and names the same item and destination.$q$, $q$يأتي قيد الخزانة بعد مذكرة النقل بست دقائق، ويذكر العينة والوجهة نفسيهما.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('ec646c05-b85a-558c-abf9-1b6412170835', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '78b099f1-b7c0-5248-951d-cfcca617c397', 'f263d153-3fee-5b8c-b1d6-0cc5ca59f17b', $q$SUPPORTS$q$, $q$The matching blue moonflower collection symbol helps identify the stored packet as the display item.$q$, $q$يساعد تطابق رمز زهرة القمر الزرقاء على تحديد الحافظة المخزنة بوصفها عينة العرض نفسها.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('d71050a8-d21f-5864-a9d7-8145a37e8fe5', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '6882f652-c0a1-5201-9825-a2631f8c1389', 'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44', $q$CONTEXTUAL$q$, $q$The old card gives the previous location; the newer signed transfer and cabinet log show the updated location.$q$, $q$تذكر البطاقة القديمة الموقع السابق؛ وتوضح مذكرة النقل الأحدث ودفتر الخزانة الموقع المحدّث.$q$) on conflict (id) do nothing;
insert into detective_evidence_relations(id, version_id, from_evidence_id, to_evidence_id, relation_type, public_explanation, public_explanation_ar) values ('944a4aab-a61e-5643-bc95-e344f5ddddcb', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '6f024c76-7e18-52b4-a743-f710dd318e12', '3e41adf7-4737-5671-89d4-4ef68ded21ee', $q$SUPPORTS$q$, $q$The intact closure is consistent with the packet remaining in secured storage after the recorded handoff.$q$, $q$يتفق الإغلاق السليم مع بقاء الحافظة في التخزين المؤمّن بعد التسليم المسجل.$q$) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('ddec645f-aa8c-5537-9c9d-b25057a8ec77', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '75a2cb26-9bc2-56ae-9aa8-e4f4bc268f5d', $q$MULTIPLE_CHOICE$q$, $q$Which detail can you directly observe in the first scene?$q$, $q$أي تفصيل يمكنك ملاحظته مباشرة في المشهد الأول؟$q$, $q$[{"id":"a","text":"The display cradle is empty and its cover looks intact","text_ar":"قاعدة العرض فارغة وغطاؤها يبدو سليمًا"},{"id":"b","text":"Farah took the packet","text_ar":"أخذت فرح الحافظة"},{"id":"c","text":"The packet was destroyed by humidity","text_ar":"أتلفت الرطوبة الحافظة"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$ملاحظة مباشرة عن المكان والحالة الظاهرة فقط؛ لا تستنتج منها هوية شخص أو سبب الغياب.$q$, $q$ملاحظة مباشرة عن المكان والحالة الظاهرة فقط؛ لا تستنتج منها هوية شخص أو سبب الغياب.$q$, array['6c281158-0402-5afb-bc49-24188314740f'::uuid]::uuid[], 8, -2, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('90ed5b88-27b2-55cf-ba92-d400c12467f3', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '75a2cb26-9bc2-56ae-9aa8-e4f4bc268f5d', $q$TRUE_FALSE$q$, $q$An empty display proves that someone stole the packet.$q$, $q$يثبت خلو منصة العرض أن شخصًا ما سرق الحافظة.$q$, $q$[]$q$::jsonb, $q${"value":"false"}$q$::jsonb, '[]'::jsonb, $q$ملاحظة مباشرة عن المكان والحالة الظاهرة فقط؛ لا تستنتج منها هوية شخص أو سبب الغياب.$q$, $q$ملاحظة مباشرة عن المكان والحالة الظاهرة فقط؛ لا تستنتج منها هوية شخص أو سبب الغياب.$q$, array['6c281158-0402-5afb-bc49-24188314740f'::uuid,'78b099f1-b7c0-5248-951d-cfcca617c397'::uuid]::uuid[], 8, -2, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('c126f447-b56b-5274-b5b9-3dea048f2210', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '75a2cb26-9bc2-56ae-9aa8-e4f4bc268f5d', $q$MULTIPLE_CHOICE$q$, $q$Select the visual clue that suggests the display area was damp.$q$, $q$حدّد القرينة البصرية التي توحي بأن منطقة العرض كانت رطبة.$q$, $q$[{"id":"a","text":"The empty, closed display","text_ar":"صندوق العرض المغلق والفارغ"},{"id":"b","text":"Condensation near the humidity gauge","text_ar":"تكاثف قرب مقياس الرطوبة"},{"id":"c","text":"The blue moonflower symbol","text_ar":"رمز زهرة القمر الزرقاء"}]$q$::jsonb, $q${"option_id":"b"}$q$::jsonb, '[]'::jsonb, $q$قرينة بصرية على الرطوبة، وليست وحدها إثباتًا أن الرطوبة تجاوزت الحد أو أن النقل كان ضروريًا.$q$, $q$قرينة بصرية على الرطوبة، وليست وحدها إثباتًا أن الرطوبة تجاوزت الحد أو أن النقل كان ضروريًا.$q$, array['c9c9f22a-3faf-532d-9ba2-749ddf46953d'::uuid]::uuid[], 10, -3, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('65c33b05-a32a-5879-8dfe-e59ad5e9c562', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '176c6d9c-4a18-59f4-9e63-25520bf55431', $q$MULTIPLE_CHOICE$q$, $q$The care guide sets a safe limit of 80%, while the log reads 86%. What does that support?$q$, $q$يحدد دليل العناية الحد الآمن عند ٨٠٪، بينما يسجل الدفتر ٨٦٪. ما الذي يدعمه ذلك؟$q$, $q$[{"id":"a","text":"A protective move to dry storage was called for","text_ar":"كان النقل الوقائي إلى التخزين الجاف مبررًا"},{"id":"b","text":"A particular student stole the seed","text_ar":"سرق طالب بعينه البذرة"},{"id":"c","text":"The packet was already missing before 3:06","text_ar":"كانت الحافظة مفقودة قبل ٣:٠٦"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$السجل يتجاوز عتبة النقل المحددة في دليل العناية؛ هذا يدعم سببًا عمليًا لكنه لا يحدد وحده من نقل الحافظة.$q$, $q$السجل يتجاوز عتبة النقل المحددة في دليل العناية؛ هذا يدعم سببًا عمليًا لكنه لا يحدد وحده من نقل الحافظة.$q$, array['4bb8d075-ca1e-5fd8-a649-1df751261c58'::uuid,'c9c9f22a-3faf-532d-9ba2-749ddf46953d'::uuid]::uuid[], 12, -3, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('e4fbbc8f-c896-568d-b067-970d238fbeb9', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '176c6d9c-4a18-59f4-9e63-25520bf55431', $q$MULTIPLE_CHOICE$q$, $q$Which record best shows that the transfer was authorized before the empty display was reported?$q$, $q$أي سجل يوضح بأفضل صورة أن النقل كان معتمدًا قبل الإبلاغ عن خلو المنصة؟$q$, $q$[{"id":"a","text":"The signed 3:10 transfer slip","text_ar":"مذكرة النقل الموقعة عند ٣:١٠"},{"id":"b","text":"The old location card","text_ar":"بطاقة الموقع القديمة"},{"id":"c","text":"A guess based on who had access","text_ar":"تخمين مبني على من كان يستطيع الدخول"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$أقوى سجل يثبت أن النقل كان موثقًا ومصرحًا به قبل اكتشاف المنصة الفارغة.$q$, $q$أقوى سجل يثبت أن النقل كان موثقًا ومصرحًا به قبل اكتشاف المنصة الفارغة.$q$, array['c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44'::uuid,'6882f652-c0a1-5201-9825-a2631f8c1389'::uuid]::uuid[], 12, -3, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('1a34f59b-2cc2-58a0-8bdc-0175751e45b7', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '176c6d9c-4a18-59f4-9e63-25520bf55431', $q$MULTIPLE_CHOICE$q$, $q$The location card still names the display shelf, but a newer transfer slip and cabinet log place S-12 in cabinet B. What is the best interpretation?$q$, $q$ما زالت بطاقة الموقع تشير إلى منصة العرض، لكن مذكرة نقل أحدث ودفتر الخزانة يضعان S-12 في الخزانة B. ما التفسير الأفضل؟$q$, $q$[{"id":"a","text":"The location card was not updated after the recorded transfer","text_ar":"لم تُحدّث بطاقة الموقع بعد النقل المسجل"},{"id":"b","text":"The old card proves the seed was stolen","text_ar":"تثبت البطاقة القديمة أن البذرة سُرقت"},{"id":"c","text":"The cabinet log must be false because it is newer","text_ar":"لا بد أن دفتر الخزانة مزيف لأنه أحدث"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$سجل قديم لم يُحدّث؛ يفسر الالتباس الإداري ولا يثبت السرقة أو الإهمال المتعمد.$q$, $q$سجل قديم لم يُحدّث؛ يفسر الالتباس الإداري ولا يثبت السرقة أو الإهمال المتعمد.$q$, array['6882f652-c0a1-5201-9825-a2631f8c1389'::uuid,'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44'::uuid,'6f024c76-7e18-52b4-a743-f710dd318e12'::uuid]::uuid[], 10, -2, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('29d23800-2eb7-5ec3-8e33-000a83c7aa0d', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '62bb4bab-567a-599d-bc16-8ab522921893', $q$MULTIPLE_CHOICE$q$, $q$Put the supported events in chronological order. Choose the correct order.$q$, $q$رتّب الأحداث التي تدعمها السجلات زمنيًا. اختر الترتيب الصحيح.$q$, $q$[{"id":"a","text":"Humidity reaches 86% → Salma signs the transfer slip → S-12 is logged into cabinet B → Farah reports the empty display","text_ar":"تصل الرطوبة إلى ٨٦٪ ← توقّع سلمى مذكرة النقل ← تُسجل S-12 في الخزانة B ← تبلغ فرح عن خلو المنصة"},{"id":"b","text":"Salma signs the transfer slip → Humidity reaches 86% → S-12 is logged into cabinet B → Farah reports the empty display","text_ar":"توقّع سلمى مذكرة النقل ← تصل الرطوبة إلى ٨٦٪ ← تُسجل S-12 في الخزانة B ← تبلغ فرح عن خلو المنصة"},{"id":"c","text":"Salma signs the transfer slip → S-12 is logged into cabinet B → Farah reports the empty display → Humidity reaches 86%","text_ar":"توقّع سلمى مذكرة النقل ← تُسجل S-12 في الخزانة B ← تبلغ فرح عن خلو المنصة ← تصل الرطوبة إلى ٨٦٪"},{"id":"d","text":"Farah reports the empty display → S-12 is logged into cabinet B → Salma signs the transfer slip → Humidity reaches 86%","text_ar":"تبلغ فرح عن خلو المنصة ← تُسجل S-12 في الخزانة B ← توقّع سلمى مذكرة النقل ← تصل الرطوبة إلى ٨٦٪"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$السجل يتجاوز عتبة النقل المحددة في دليل العناية؛ هذا يدعم سببًا عمليًا لكنه لا يحدد وحده من نقل الحافظة.$q$, $q$السجل يتجاوز عتبة النقل المحددة في دليل العناية؛ هذا يدعم سببًا عمليًا لكنه لا يحدد وحده من نقل الحافظة.$q$, array['4bb8d075-ca1e-5fd8-a649-1df751261c58'::uuid,'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44'::uuid,'6f024c76-7e18-52b4-a743-f710dd318e12'::uuid,'6c281158-0402-5afb-bc49-24188314740f'::uuid]::uuid[], 15, -4, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('b923d004-7154-567e-bd56-800409b074c0', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '62bb4bab-567a-599d-bc16-8ab522921893', $q$MULTIPLE_CHOICE$q$, $q$Which claim goes beyond the evidence currently available?$q$, $q$أي ادعاء يتجاوز الأدلة المتاحة حاليًا؟$q$, $q$[{"id":"a","text":"The seed packet was moved to cabinet B after a high humidity reading","text_ar":"نُقلت الحافظة إلى الخزانة B بعد قراءة رطوبة مرتفعة"},{"id":"b","text":"Farah stole the packet because she first noticed it was gone","text_ar":"سرقت فرح الحافظة لأنها أول من لاحظ غيابها"},{"id":"c","text":"The location card had not been updated","text_ar":"لم تُحدّث بطاقة الموقع"}]$q$::jsonb, $q${"option_id":"b"}$q$::jsonb, '[]'::jsonb, $q$أقوى سجل يثبت أن النقل كان موثقًا ومصرحًا به قبل اكتشاف المنصة الفارغة.$q$, $q$أقوى سجل يثبت أن النقل كان موثقًا ومصرحًا به قبل اكتشاف المنصة الفارغة.$q$, array['c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44'::uuid,'6f024c76-7e18-52b4-a743-f710dd318e12'::uuid,'6882f652-c0a1-5201-9825-a2631f8c1389'::uuid]::uuid[], 15, -4, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('4777a88c-b15c-5bce-b584-f9d35412ae78', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '62bb4bab-567a-599d-bc16-8ab522921893', $q$FINAL_CONCLUSION$q$, $q$What is the fairest conclusion supported by the records?$q$, $q$ما الاستنتاج الأكثر إنصافًا الذي تدعمه السجلات؟$q$, $q$[{"id":"a","text":"Salma documented a protective move of S-12 to cabinet B after humidity exceeded the safe limit; the old card was not updated, and the records do not support theft","text_ar":"وثّقت سلمى نقلًا وقائيًا للعينة S-12 إلى الخزانة B بعد تجاوز الرطوبة الحد الآمن؛ ولم تُحدّث البطاقة القديمة، ولا تدعم السجلات فرضية السرقة"},{"id":"b","text":"Farah must have stolen it because she discovered the empty display","text_ar":"لا بد أن فرح سرقتها لأنها اكتشفت خلو المنصة"},{"id":"c","text":"The seed was destroyed because the greenhouse was damp","text_ar":"تلفت البذرة لأن البيت الزجاجي كان رطبًا"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$The packet was not shown to be stolen. The greenhouse log recorded 86% humidity, above the 80% care limit. Supervisor Salma signed a transfer at 3:10 p.m., and the cabinet log records the same S-12 packet in dry cabinet B at 3:16. The packet is still safely stored there, while the old display-location card was never updated. The records support a documented protective move and an out-of-date card, not theft or blame of a student.$q$, $q$لا تثبت السجلات أن الحافظة سُرقت. سجل دفتر البيت الزجاجي رطوبة بنسبة ٨٦٪، أعلى من حد العناية البالغ ٨٠٪. ووقعت المشرفة سلمى مذكرة نقل عند ٣:١٠ عصرًا، ثم سجل دفتر الخزانة العينة S-12 نفسها في الخزانة الجافة B عند ٣:١٦. ما زالت الحافظة محفوظة هناك، بينما لم تُحدّث بطاقة موقع العرض القديمة. تدعم السجلات نقلًا وقائيًا موثقًا وبطاقة غير محدثة، لا السرقة ولا اتهام طالبة.$q$, array['4bb8d075-ca1e-5fd8-a649-1df751261c58'::uuid,'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44'::uuid,'6882f652-c0a1-5201-9825-a2631f8c1389'::uuid,'f263d153-3fee-5b8c-b1d6-0cc5ca59f17b'::uuid,'6f024c76-7e18-52b4-a743-f710dd318e12'::uuid,'3e41adf7-4737-5671-89d4-4ef68ded21ee'::uuid]::uuid[], 20, -5, 3) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('2e05d4bf-57c0-5e5d-96b3-ea07286b6436', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$Salma Nabil$q$, $q$سلمى نبيل$q$, $q$Maintains the seed collection and can authorize a protective storage transfer.$q$, $q$تعتني بمجموعة البذور ويمكنها اعتماد نقل وقائي إلى التخزين. نقلت حافظة العينة S-12 بعد تسجيل رطوبة مرتفعة، ووقعت مذكرة النقل.$q$, $q$مشرفة البيت الزجاجي$q$, $q$Greenhouse supervisor$q$, $q${"15:06":"Humidity above the seed-care limit","15:10":"Transfer slip signed","15:16":"Cabinet B handoff recorded"}$q$::jsonb, $q$تتوافق أحرف توقيعها في مذكرة النقل ودفتر الخزانة مع وقت نقل الحافظة.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('22ca7713-0f97-52d3-90b9-215c4dae2969', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$Farah Youssef$q$, $q$فرح يوسف$q$, $q$Helped prepare the science showcase and first noticed that the display cradle was empty.$q$, $q$ساعدت في إعداد عرض العلوم وكانت أول من لاحظ خلو منصة العرض. وضعت رمز زهرة القمر على منصة العرض صباحًا، ثم أبلغت عن خلوها عند ٣:٣٠.$q$, $q$متطوعة عرض من الطالبات$q$, $q$Student display volunteer$q$, $q${"14:40":"Display checked before showcase","15:30":"Empty cradle reported"}$q$::jsonb, $q$لم تشاهد عملية النقل وقالت بوضوح إنها لا تعرف من نقل الحافظة حتى راجعت السجلات.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('c55fb4cd-564a-5ecd-b5d8-93b706ca545c', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$Omar Adel$q$, $q$عمر عادل$q$, $q$Maintains location cards and helped prepare the seed-storage register.$q$, $q$يتولى بطاقات المواقع وساعد في إعداد سجل تخزين البذور. ترك بطاقة الموقع القديمة على المنصة ولم يسجل تحديثًا بعد توقيع مذكرة النقل.$q$, $q$مساعد الجرد$q$, $q$Inventory helper$q$, $q${"14:50":"Location card checked","15:30":"Old location card still displayed"}$q$::jsonb, $q$أقر بأن البطاقة لم تُحدّث بعد، ولا يثبت ذلك أنه نقل الحافظة أو أخفاها.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('03197644-abfb-5b47-9980-0bf1cd87fc95', '2e05d4bf-57c0-5e5d-96b3-ea07286b6436', $q$I signed a transfer for S-12 after the humidity reading passed the safe limit, then placed it in cabinet B.$q$, $q$وقعت مذكرة نقل العينة S-12 بعد تجاوز قراءة الرطوبة الحد الآمن، ثم وضعتها في الخزانة B.$q$, $q$TRUE$q$, array['4bb8d075-ca1e-5fd8-a649-1df751261c58'::uuid,'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44'::uuid,'6f024c76-7e18-52b4-a743-f710dd318e12'::uuid]::uuid[], $q$تتفق إفادة سلمى مع سجل الرطوبة ومذكرة النقل ودفتر الخزانة. الأدلة تدعم نقلًا وقائيًا موثقًا.$q$, $q$تتفق إفادة سلمى مع سجل الرطوبة ومذكرة النقل ودفتر الخزانة. الأدلة تدعم نقلًا وقائيًا موثقًا.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('365c071c-cc88-5e23-837d-8ae5cfd46774', '22ca7713-0f97-52d3-90b9-215c4dae2969', $q$The display was empty when I checked at 3:30, but I did not see who moved the packet.$q$, $q$كانت منصة العرض فارغة عندما تفقدتها عند ٣:٣٠، لكنني لم أرَ من نقل الحافظة.$q$, $q$TRUE$q$, array['6c281158-0402-5afb-bc49-24188314740f'::uuid,'6f024c76-7e18-52b4-a743-f710dd318e12'::uuid]::uuid[], $q$تتفق مع مشهد المنصة الخالية وسجل الخزانة، ولا تدعي معرفة لا تدعمها الأدلة.$q$, $q$تتفق مع مشهد المنصة الخالية وسجل الخزانة، ولا تدعي معرفة لا تدعمها الأدلة.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('572c183e-e586-5a79-a147-27b771b20f4e', 'c55fb4cd-564a-5ecd-b5d8-93b706ca545c', $q$The location card still says display shelf; I had not updated it after the transfer.$q$, $q$ما زالت بطاقة الموقع تشير إلى رف العرض؛ لم أكن قد حدّثتها بعد النقل.$q$, $q$TRUE$q$, array['6882f652-c0a1-5201-9825-a2631f8c1389'::uuid,'c71ebf4a-73ab-5d9a-9e8c-9556bf80fb44'::uuid,'6f024c76-7e18-52b4-a743-f710dd318e12'::uuid]::uuid[], $q$تتفق إفادة عمر مع البطاقة القديمة ومذكرة النقل. تأخر تحديث السجل لا يثبت إخفاء الحافظة أو سرقتها.$q$, $q$تتفق إفادة عمر مع البطاقة القديمة ومذكرة النقل. تأخر تحديث السجل لا يثبت إخفاء الحافظة أو سرقتها.$q$) on conflict (id) do nothing;
