insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('b7046a14-7cc3-5076-a4d6-98168d7fd7d2', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$humidity_exceeds_limit$q$, $q$Humidity reaches 86%$q$, $q$تصل الرطوبة إلى ٨٦٪$q$, $q$15:06$q$, 2) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('09215237-29cc-5b20-8801-62c77ddd62a5', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$transfer_signed$q$, $q$Salma signs the S-12 transfer slip$q$, $q$توقّع سلمى مذكرة نقل S-12$q$, $q$15:10$q$, 3) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('0ba71416-f539-5571-9ea4-f8be61393004', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$cabinet_entry$q$, $q$S-12 is logged into dry cabinet B$q$, $q$تُسجل S-12 في الخزانة الجافة B$q$, $q$15:16$q$, 4) on conflict (id) do nothing;
insert into detective_timeline_events(id, version_id, event_key, label, label_ar, window_key, position) values ('516bf6c1-6758-57e8-90df-60ae0ce28cfd', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$empty_display_reported$q$, $q$Farah reports the empty display$q$, $q$تبلغ فرح عن خلو منصة العرض$q$, $q$15:30$q$, 5) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('042cd830-3662-5e2a-a803-b187121fc02f', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '75a2cb26-9bc2-56ae-9aa8-e4f4bc268f5d', $q$An empty stand tells you where the packet is not. Look for records that explain where it went.$q$, $q$تخبرك المنصة الفارغة أين لا توجد الحافظة. ابحث عن سجلات تشرح أين ذهبت.$q$, '{}'::jsonb, -1, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('b8a98b81-2420-5950-a83b-90c05768c1e7', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '176c6d9c-4a18-59f4-9e63-25520bf55431', $q$Compare the humidity reading with the care threshold, then check whether a transfer was signed before 3:30.$q$, $q$قارن قراءة الرطوبة بحد العناية، ثم تحقق مما إذا كان النقل قد وُقّع قبل ٣:٣٠.$q$, '{}'::jsonb, -2, 2) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('92233ffe-bd60-5963-9d4e-055192334ee5', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', '62bb4bab-567a-599d-bc16-8ab522921893', $q$The newest location record and the old display card disagree. A stale record is not the same as a missing object.$q$, $q$يختلف أحدث سجل للموقع عن بطاقة العرض القديمة. السجل المتأخر ليس هو نفسه الغرض المفقود.$q$, '{}'::jsonb, -3, 3) on conflict (id) do nothing;
insert into detective_solutions(id, version_id, public_reveal, public_reveal_ar, solution_key, alternative_hypotheses, educational_explanation, educational_explanation_ar) values ('998834da-4e36-5ac4-8cd7-4309570452fd', 'f1f57913-2d9f-5ada-9cb8-1326514fc97a', $q$The packet was not shown to be stolen. The greenhouse log recorded 86% humidity, above the 80% care limit. Supervisor Salma signed a transfer at 3:10 p.m., and the cabinet log records the same S-12 packet in dry cabinet B at 3:16. The packet is still safely stored there, while the old display-location card was never updated. The records support a documented protective move and an out-of-date card, not theft or blame of a student.$q$, $q$لا تثبت السجلات أن الحافظة سُرقت. سجل دفتر البيت الزجاجي رطوبة بنسبة ٨٦٪، أعلى من حد العناية البالغ ٨٠٪. ووقعت المشرفة سلمى مذكرة نقل عند ٣:١٠ عصرًا، ثم سجل دفتر الخزانة العينة S-12 نفسها في الخزانة الجافة B عند ٣:١٦. ما زالت الحافظة محفوظة هناك، بينما لم تُحدّث بطاقة موقع العرض القديمة. تدعم السجلات نقلًا وقائيًا موثقًا وبطاقة غير محدثة، لا السرقة ولا اتهام طالبة.$q$, $q${"final_question":"4777a88c-b15c-5bce-b584-f9d35412ae78"}$q$::jsonb, $q$[{"en":"Farah stole the packet because she found the empty display.","ar":"سرقت فرح الحافظة لأنها وجدت المنصة فارغة.","why_wrong_en":"Finding an empty stand does not show who moved the packet. The signed transfer and cabinet entry document a protective move before Farah's report.","why_wrong_ar":"العثور على منصة فارغة لا يحدد من نقل الحافظة. توثق مذكرة النقل ودفتر الخزانة نقلًا وقائيًا قبل بلاغ فرح."},{"en":"The seed packet was destroyed by humidity.","ar":"أتلفت الرطوبة حافظة البذور.","why_wrong_en":"The records place the packet in dry cabinet B, and the matching collection symbol identifies it there. No damage is recorded.","why_wrong_ar":"تضع السجلات الحافظة في الخزانة الجافة B، ويحددها رمز المجموعة المطابق. ولا يوجد تلف مسجل."},{"en":"The old location card proves the packet was still on the display shelf.","ar":"تثبت بطاقة الموقع القديمة أن الحافظة بقيت على رف العرض.","why_wrong_en":"The card was not updated. The newer transfer slip and cabinet log record the later location.","why_wrong_ar":"لم تُحدّث البطاقة. وتسجل مذكرة النقل ودفتر الخزانة الأحدث الموقع اللاحق."}]$q$::jsonb, $q$A careful investigator separates absence from theft, and a clue from proof. The damp shelf suggests a condition to check; the signed humidity log gives the measurement; the transfer slip documents an authorized decision; and the cabinet log independently records where the packet went. The old location card explains the confusion but is not evidence of a crime. The conclusion should stop where the records stop.$q$, $q$يفصل المحقق الدقيق بين الغياب والسرقة، وبين القرينة والإثبات. يوحي الرف الرطب بظرف يستحق الفحص؛ ويقدم سجل الرطوبة الموقع القياس؛ وتوثق مذكرة النقل قرارًا معتمدًا؛ ويسجل دفتر الخزانة بصورة مستقلة أين ذهبت الحافظة. تفسر بطاقة الموقع القديمة سبب الالتباس، لكنها ليست دليل جريمة. ينبغي أن يتوقف الاستنتاج عند حدود السجلات.$q$) on conflict (id) do nothing;
